package org.itroboc.core

/**
 * Impression-scoped immutable membership view for BeetleMind cognition.
 *
 * I-04f intentionally carries only board identity, the correlated target seat,
 * and canonical card membership. Main-owned edit history, repair state,
 * DDS/TNT, messages, and reducer behavior do not cross this boundary.
 */
class ActiveBoardView private constructor(
    val boardNumber: Int,
    val targetSeat: Seat,
    private val northCards: Long,
    private val eastCards: Long,
    private val southCards: Long,
    private val westCards: Long,
) {
    init {
        require(boardNumber > 0) { "Active board number must be positive" }
    }

    val targetCardCount: Int
        get() = cardsOf(targetSeat).countOneBits()

    fun contains(card: CardId): Boolean = seatContaining(card) != null

    fun seatContaining(card: CardId): Seat? {
        val bit = card.bit()
        return Seat.entries.firstOrNull { seat -> cardsOf(seat) and bit != 0L }
    }

    fun isInTargetHand(card: CardId): Boolean =
        cardsOf(targetSeat) and card.bit() != 0L

    fun isInAnotherHand(card: CardId): Boolean =
        seatContaining(card)?.let { it != targetSeat } == true

    fun isTargetHandComplete(): Boolean = targetCardCount == HandState.FULL_HAND_SIZE

    override fun equals(other: Any?): Boolean =
        this === other ||
            other is ActiveBoardView &&
            boardNumber == other.boardNumber &&
            targetSeat == other.targetSeat &&
            northCards == other.northCards &&
            eastCards == other.eastCards &&
            southCards == other.southCards &&
            westCards == other.westCards

    override fun hashCode(): Int {
        var result = boardNumber
        result = 31 * result + targetSeat.hashCode()
        result = 31 * result + northCards.hashCode()
        result = 31 * result + eastCards.hashCode()
        result = 31 * result + southCards.hashCode()
        result = 31 * result + westCards.hashCode()
        return result
    }

    override fun toString(): String =
        "ActiveBoardView(boardNumber=$boardNumber, targetSeat=$targetSeat, " +
            "counts=${Seat.entries.joinToString(prefix = "[", postfix = "]") { seat ->
                "${seat.symbol}:${cardsOf(seat).countOneBits()}"
            }})"

    private fun cardsOf(seat: Seat): Long = when (seat) {
        Seat.NORTH -> northCards
        Seat.EAST -> eastCards
        Seat.SOUTH -> southCards
        Seat.WEST -> westCards
    }

    companion object {
        /** Project the authoritative post-reducer board for one explicit target. */
        fun from(state: BoardEditState, targetSeat: Seat): ActiveBoardView =
            ActiveBoardView(
                boardNumber = state.boardNumber,
                targetSeat = targetSeat,
                northCards = state.boardState.handOf(Seat.NORTH).membershipBits(),
                eastCards = state.boardState.handOf(Seat.EAST).membershipBits(),
                southCards = state.boardState.handOf(Seat.SOUTH).membershipBits(),
                westCards = state.boardState.handOf(Seat.WEST).membershipBits(),
            )

        private fun HandState.membershipBits(): Long =
            cards().fold(0L) { bits, card -> bits or card.bit() }

        private fun CardId.bit(): Long =
            1L shl (suit.ordinal * Rank.entries.size + rank.ordinal)
    }
}

