package org.itroboc.app

import android.content.ActivityNotFoundException
import android.content.Intent
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.dp
import org.itroboc.vision.BarcodeDecodeResult
import org.itroboc.core.*
import java.util.concurrent.atomic.AtomicBoolean

@OptIn(ExperimentalLayoutApi::class)
@Composable
fun AdminEditScreen(
    editor: DeckProfileEditor,
    hasCameraPermission: Boolean,
    onSave: (DeckProfile) -> Unit,
    onBack: () -> Unit
) {
    var selectedSuit by remember { mutableStateOf(Suit.SPADES) }
    var selectedRank by remember { mutableStateOf(Rank.ACE) }
    val selectedCard = CardId(selectedSuit, selectedRank)

    var isReadOnly by remember(editor) { mutableStateOf(editor.hasAliasesForEveryCard()) }
    var autoAdvance by remember { mutableStateOf(true) }
    var lastResultMessage by remember { mutableStateOf<String?>(null) }
    var aliasDetailsDialog by remember { mutableStateOf<AdminAliasDetails?>(null) }
    var isDirty by remember { mutableStateOf(false) }
    var showUnsavedChangesDialog by remember { mutableStateOf(false) }

    var frameDebugInfo by remember { mutableStateOf<FrameDebugInfo?>(null) }
    var cameraDecodeInfo by remember { mutableStateOf<String?>(null) }
    var scanRequested by remember { mutableStateOf(false) }
    var pendingScanCard by remember { mutableStateOf<CardId?>(null) }
    var debugLogStatus by remember { mutableStateOf<String?>(null) }
    val pendingScanRequest = remember { AtomicBoolean(false) }
    val frameDecoder = remember { CameraFrameDecoder() }
    val scanEvidenceByAlias = remember { mutableStateMapOf<String, AdminAliasScanEvidence>() }

    // Trigger recomposition when editor state changes
    var updateTrigger by remember { mutableIntStateOf(0) }

    val context = LocalContext.current
    val debugLogManager = remember(context) { AdminEditScanDebugLogManager(context) }

    LaunchedEffect(isReadOnly) {
        if (isReadOnly) {
            pendingScanRequest.set(false)
            scanRequested = false
            pendingScanCard = null
        }
    }

    fun advanceToNextUnmappedCardOrReportCompletion() {
        val allCards = Suit.entries.flatMap { suit ->
            Rank.entries.map { rank -> CardId(suit, rank) }
        }
        val nextUnmapped = allCards.firstOrNull { !editor.isMapped(it) }
        if (nextUnmapped != null) {
            selectedSuit = nextUnmapped.suit
            selectedRank = nextUnmapped.rank
        } else {
            lastResultMessage = "Profile complete! All 52 cards mapped."
        }
    }

    fun applySignature(targetCard: CardId, rawSignature: String, detectionLabel: String) {
        if (isReadOnly) return
        val result = editor.assign(rawSignature, targetCard)
        lastResultMessage = when (result) {
            is DeckProfileEditResult.Assigned ->
                "$detectionLabel assigned to ${targetCard.prettyString}"
            is DeckProfileEditResult.AlreadyAssignedToSelected ->
                "$detectionLabel already exists for ${targetCard.prettyString}"
            is DeckProfileEditResult.SignatureConflict ->
                "$detectionLabel CONFLICT: already mapped to ${result.existingCard.prettyString}"
            else -> "No card selected"
        }

        if (result is DeckProfileEditResult.Assigned && autoAdvance) {
            advanceToNextUnmappedCardOrReportCompletion()
        }
        if (result is DeckProfileEditResult.Assigned) {
            isDirty = true
        }
        updateTrigger++
    }

    val selectedCardAliases = editor.getAliases(selectedCard)
    val readOnlyAvailable = editor.hasAliasesForEveryCard()

    LaunchedEffect(readOnlyAvailable) {
        if (!readOnlyAvailable && isReadOnly) {
            isReadOnly = false
        }
    }

    Row(modifier = Modifier.fillMaxSize()) {
        // Left Part: 52-card mapping grid (Stretched to fill height)
        Column(
            modifier = Modifier
                .weight(0.4f)
                .fillMaxHeight()
                .padding(8.dp)
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 8.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    text = "Card Mapping",
                    style = MaterialTheme.typography.titleMedium,
                )
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Checkbox(
                        checked = isReadOnly,
                        onCheckedChange = { isReadOnly = it },
                        enabled = readOnlyAvailable
                    )
                    Text("Read only", style = MaterialTheme.typography.labelMedium)
                    Spacer(modifier = Modifier.width(8.dp))
                    Checkbox(
                        checked = autoAdvance,
                        onCheckedChange = { autoAdvance = it }
                    )
                    Text("Auto-advance", style = MaterialTheme.typography.labelMedium)
                }
            }
            if (!readOnlyAvailable) {
                Text(
                    text = "Read only unlocks once all 52 cards have at least one alias.",
                    style = MaterialTheme.typography.labelSmall,
                    color = Color.Gray,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = TextAlign.End,
                )
            }

            val suits = Suit.entries
            val ranks = Rank.entries

            // Header row
            Row(
                modifier = Modifier.fillMaxWidth().weight(1f),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                suits.forEach { suit ->
                    Box(
                        modifier = Modifier.weight(1f).fillMaxHeight(),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(text = suit.prettySymbol, style = ItrobocTextStyles.AdminGridSuit)
                    }
                }
            }

            // Card rows (13 rows)
            ranks.forEach { rank ->
                Row(
                    modifier = Modifier.fillMaxWidth().weight(1f).padding(top = 4.dp),
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    suits.forEach { suit ->
                        val card = CardId(suit, rank)
                        val isMapped = editor.isMapped(card)
                        val isSelected = card == selectedCard

                        Box(modifier = Modifier.weight(1f)) {
                            CardButton(
                                card = card,
                                isMapped = isMapped,
                                isSelected = isSelected,
                                onClick = {
                                    selectedSuit = suit
                                    selectedRank = rank
                                }
                            )
                        }
                    }
                }
            }
        }

        // Right Part: Scanner and controls
        Column(
            modifier = Modifier
                .weight(0.6f)
                .fillMaxHeight()
                .padding(8.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Camera Preview area
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .fillMaxHeight(0.6f)
                    .background(Color.DarkGray, RoundedCornerShape(8.dp)),
                contentAlignment = Alignment.Center
            ) {
                if (!isReadOnly && hasCameraPermission) {
                    BarcodeCameraScanner(
                        consumeScanRequest = { pendingScanRequest.compareAndSet(true, false) },
                        frameDecoder = frameDecoder,
                        onScanProcessed = { streamOutcome ->
                            val scanOutcome = streamOutcome.outcome
                            val scanCard = pendingScanCard ?: selectedCard
                            frameDebugInfo = scanOutcome.frameDebugInfo
                            cameraDecodeInfo = scanOutcome.describe()
                            scanRequested = false
                            pendingScanCard = null
                            debugLogManager.appendScanRecord(
                                selectedCard = scanCard.prettyString,
                                outcome = scanOutcome,
                                deckProfileMatchCount = scanOutcome.deckProfileMatchCount(editor.toDeckProfile()),
                            )

                            when (scanOutcome) {
                                is CameraScanOutcome.Decoded -> when (val decodeResult = scanOutcome.decodeResult) {
                                    is BarcodeDecodeResult.Found -> {
                                        val signature = decodeResult.signature
                                        val detectionLabel = "Detected ${signature.rawSignature} (${signature.confidence.formatAsUiConfidence()})"
                                        scanEvidenceByAlias[signature.rawSignature] = signature.toAdminAliasScanEvidence()
                                        applySignature(
                                            targetCard = scanCard,
                                            rawSignature = signature.rawSignature,
                                            detectionLabel = detectionLabel,
                                        )
                                    }
                                    is BarcodeDecodeResult.NotFound -> {
                                        lastResultMessage = decodeResult.reason
                                    }
                                    is BarcodeDecodeResult.Ambiguous -> {
                                        lastResultMessage = scanOutcome.describe()
                                    }
                                }
                                is CameraScanOutcome.ConversionFailed -> {
                                    lastResultMessage = scanOutcome.reason
                                }
                            }
                        },
                        modifier = Modifier.fillMaxSize(),
                    )
                    BarcodeGuideOverlay(
                        guideSpec = barcodeScanGuideSpec,
                        modifier = Modifier.fillMaxSize(),
                    )
                } else if (isReadOnly) {
                    AdminReadOnlyCardPreview(
                        card = selectedCard,
                        aliases = selectedCardAliases,
                    )
                } else {
                    Text(
                        text = "Camera permission is required for scanning.",
                        color = Color.LightGray,
                        modifier = Modifier.padding(16.dp),
                        textAlign = TextAlign.Center
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Selected card status
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.Center
            ) {
                Button(
                    onClick = {
                        pendingScanRequest.set(true)
                        scanRequested = true
                        pendingScanCard = selectedCard
                        cameraDecodeInfo = null
                        lastResultMessage = "Waiting for next camera frame..."
                        updateTrigger++ // Force UI refresh
                    },
                    enabled = !isReadOnly && hasCameraPermission,
                    modifier = Modifier.height(44.dp),
                    contentPadding = PaddingValues(horizontal = 18.dp, vertical = 0.dp)
                ) {
                    Text("Scan", style = MaterialTheme.typography.labelLarge)
                }
                Spacer(modifier = Modifier.width(16.dp))
                Text(
                    text = "Selected: ${selectedCard.prettyString}",
                    style = MaterialTheme.typography.headlineSmall,
                    fontWeight = FontWeight.Bold
                )
                Spacer(modifier = Modifier.width(16.dp))
                Button(
                    onClick = {
                        val mockSig = "0x${(1000..9999).random().toString(16).uppercase()}"
                        cameraDecodeInfo = "Mock fallback used"
                        applySignature(
                            targetCard = selectedCard,
                            rawSignature = mockSig,
                            detectionLabel = "Mock signature $mockSig",
                        )
                    },
                    enabled = !isReadOnly,
                    modifier = Modifier.height(32.dp),
                    contentPadding = PaddingValues(horizontal = 12.dp, vertical = 0.dp)
                ) {
                    Text("Mock", style = MaterialTheme.typography.labelSmall)
                }
            }
            val aliases = selectedCardAliases
            Text(
                text = if (aliases.isEmpty()) {
                    "Unmapped • Aliases: none"
                } else {
                    "Mapped • Aliases: ${aliases.joinToString()}"
                },
                style = MaterialTheme.typography.bodyMedium,
                color = if (aliases.isEmpty()) Color.Red else Color.Unspecified
            )
            if (aliases.isNotEmpty()) {
                Spacer(modifier = Modifier.height(8.dp))
                FlowRow(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    aliases.forEach { alias ->
                        SuggestionChip(
                            onClick = {
                                aliasDetailsDialog = AdminAliasDetails(
                                    rawSignature = alias,
                                    evidence = scanEvidenceByAlias[alias],
                                )
                            },
                            label = { Text(alias) }
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.weight(1f))

            // Controls
            frameDebugInfo?.let {
                Text(
                    text = it.describe(),
                    style = MaterialTheme.typography.labelSmall,
                    color = Color.Gray
                )
            }
            cameraDecodeInfo?.let {
                Text(
                    text = it,
                    style = MaterialTheme.typography.labelSmall,
                    color = Color.Gray
                )
            }

            lastResultMessage?.let {
                Text(it, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.primary)
            }
            Text(
                text = "Log: ${debugLogManager.logFile.absolutePath}",
                style = MaterialTheme.typography.labelSmall,
                color = Color.Gray,
                maxLines = 3,
                overflow = TextOverflow.Ellipsis,
            )
//            debugLogStatus?.let {
//                Text(
//                    text = it,
//                    style = MaterialTheme.typography.labelSmall,
//                    color = Color.Gray,
//                    maxLines = 2,
//                    overflow = TextOverflow.Ellipsis,
//                )
//            }

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Button(
                    onClick = {
                        onSave(editor.toDeckProfile())
                        isDirty = false
                    },
                    enabled = !isReadOnly,
                    modifier = Modifier.weight(1f)
                ) {
                    Text("Save")
                }
                Button(
                    onClick = {
                        if (isDirty && !isReadOnly) {
                            showUnsavedChangesDialog = true
                        } else {
                            onBack()
                        }
                    },
                    modifier = Modifier.weight(1f)
                ) {
                    Text("Back")
                }
            }
            OutlinedButton(
                onClick = {
                    val shareIntent = debugLogManager.createShareIntent()
                    if (shareIntent == null) {
                        debugLogStatus = "No debug log to share yet."
                    } else {
                        try {
                            context.startActivity(Intent.createChooser(shareIntent, "Share scan debug log"))
                            debugLogStatus = "Opened Android share sheet for scan debug log."
                        } catch (_: ActivityNotFoundException) {
                            debugLogStatus = "No app available to share the scan debug log."
                        }
                    }
                },
                modifier = Modifier.fillMaxWidth(),
            ) {
                Text("Share Debug Log")
            }
        }
    }

    aliasDetailsDialog?.let { details ->
        AlertDialog(
            onDismissRequest = { aliasDetailsDialog = null },
            title = { Text("Alias details") },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    details.displayLines().forEach { line ->
                        Text(
                            text = line,
                            style = MaterialTheme.typography.bodySmall,
                        )
                    }
                }
            },
            confirmButton = {
                if (!isReadOnly) {
                    TextButton(onClick = {
                        val alias = details.rawSignature
                        editor.remove(alias)
                        lastResultMessage = "Removed alias $alias"
                        isDirty = true
                        aliasDetailsDialog = null
                        updateTrigger++
                    }) {
                        Text("Remove")
                    }
                }
            },
            dismissButton = {
                TextButton(onClick = { aliasDetailsDialog = null }) {
                    Text("Close")
                }
            }
        )
    }

    if (showUnsavedChangesDialog) {
        AlertDialog(
            onDismissRequest = { showUnsavedChangesDialog = false },
            title = { Text("Profile was modified.") },
            text = { Text("Save changes?") },
            confirmButton = {
                TextButton(onClick = {
                    onSave(editor.toDeckProfile())
                    isDirty = false
                    showUnsavedChangesDialog = false
                    onBack()
                }) {
                    Text("Save")
                }
            },
            dismissButton = {
                TextButton(onClick = {
                    isDirty = false
                    showUnsavedChangesDialog = false
                    onBack()
                }) {
                    Text("Discard")
                }
            }
        )
    }
}

@Composable
fun CardButton(
    card: CardId,
    isMapped: Boolean,
    isSelected: Boolean,
    onClick: () -> Unit
) {
    val backgroundColor = if (isMapped) Color(0xFF4CAF50) else Color(0xFFFFEB3B)
    val borderColor = if (isSelected) Color.Black else Color.Transparent
    val borderWidth = if (isSelected) 3.dp else 0.dp

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .fillMaxHeight()
            .background(backgroundColor, RoundedCornerShape(4.dp))
            .border(borderWidth, borderColor, RoundedCornerShape(4.dp))
            .clickable(onClick = onClick),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = card.rank.symbol.toString(),
            fontWeight = FontWeight.Bold,
            style = ItrobocTextStyles.AdminGridRank,
            color = Color.Black
        )
    }
}

private val CardId.prettyString: String
    get() = "${suit.prettySymbol}${rank.symbol}"

private fun CameraScanOutcome.deckProfileMatchCount(deckProfile: DeckProfile): Int = when (this) {
    is CameraScanOutcome.Decoded -> when (val result = decodeResult) {
        is BarcodeDecodeResult.Found -> if (deckProfile.lookup(result.signature.rawSignature) != null) 1 else 0
        is BarcodeDecodeResult.Ambiguous -> result.candidates
            .map { it.rawSignature }
            .distinct()
            .count { deckProfile.lookup(it) != null }
        is BarcodeDecodeResult.NotFound -> 0
    }
    is CameraScanOutcome.ConversionFailed -> 0
}

private fun Double.formatAsUiConfidence(): String = "%.2f".format(this)

package org.itroboc.app

import android.Manifest
import android.app.Application
import android.content.Context
import android.content.pm.PackageManager
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.core.content.ContextCompat
import androidx.core.content.edit
import androidx.lifecycle.AndroidViewModel
import org.itroboc.core.BoardProgressSummary
import org.itroboc.core.BuiltInDeckProfiles
import org.itroboc.core.DeckProfile
import org.itroboc.core.DeckProfileSignatureModels
import java.io.File

/**
 * Durable anchor for ITROBOC app state.
 * Survives configuration changes (orientation, etc).
 * Now includes TD autosave persistence.
 */
class ItrobocMainViewModel(application: Application) : AndroidViewModel(application) {
    private val prefs = application.getSharedPreferences("itroboc_settings", Context.MODE_PRIVATE)
    private val autosaveManager = TdSessionAutosaveManager(application)
    private val snapTuningPreferences = SnapTuningPreferences(
        SharedPreferencesSnapTuningStore(prefs),
    )

    // --- Navigation State ---
    var currentScreen by mutableStateOf<Screen>(Screen.MainMenu)
    var barcodeOrientationMode by mutableStateOf(BarcodeOrientationMode.BRM)
    var tdFeedMode by mutableStateOf(TdFeedMode.STREAM)
    var snapTuningSettings by mutableStateOf(snapTuningPreferences.load())
        private set

    // --- Profile State ---
    private val builtInDefault = BuiltInDeckProfiles.defaultProfile()
    private val builtInDefaultMetadata = builtInDefault.metadata.toProfileListItem()
    private val builtInDemo = BuiltInDeckProfiles.demoBridge52()
    private val builtInDemoMetadata = builtInDemo.metadata.toProfileListItem()

    var profileState by mutableStateOf(
        AdminProfileUiState(
            profiles = listOf(builtInDefaultMetadata, builtInDemoMetadata),
            activeProfileId = builtInDefaultMetadata.id,
        )
    )

    var editedProfiles by mutableStateOf(
        mapOf(
            builtInDefaultMetadata.id to builtInDefault,
            builtInDemoMetadata.id to builtInDemo,
        )
    )

    val activeProfileItem: ProfileListItem
        get() = profileState.activeProfile ?: builtInDefaultMetadata

    val activeDeckProfile: DeckProfile
        get() = editedProfiles[activeProfileItem.id] ?: builtInDefault

    // --- Operational Status ---
    var hasCameraPermission by mutableStateOf(
        ContextCompat.checkSelfPermission(
            application,
            Manifest.permission.CAMERA
        ) == PackageManager.PERMISSION_GRANTED
    )
        private set

    // --- TD Session State ---
    var sessionState by mutableStateOf(TdSessionState())

    // --- Autosave Settings ---
    var autosaveEnabled by mutableStateOf(prefs.getBoolean("autosave_enabled", true))
        private set
    var autosavePrefix by mutableStateOf(prefs.getString("autosave_prefix", "ITROBOC-autosave") ?: "ITROBOC-autosave")
        private set
    val autosavePath: String
        get() = File(autosaveManager.getAutosaveDirectory(), currentAutosaveFilename).absolutePath

    private var currentAutosaveFilename = autosaveManager.generateFilename(autosavePrefix)

    // --- Housekeeping State ---
    var oldAutosaveFiles by mutableStateOf<List<File>>(emptyList())

    init {
        // Initial restore with midnight fallback
        sessionState = autosaveManager.smartRestore(autosavePrefix, sessionState)

        // Check for old files
        oldAutosaveFiles = autosaveManager.findOldAutosaves(autosavePrefix)
    }

    // --- Actions ---
    fun updateCameraPermission(granted: Boolean) {
        hasCameraPermission = granted
    }

    fun navigateTo(screen: Screen) {
        currentScreen = screen
    }

    fun updateOrientation(mode: BarcodeOrientationMode) {
        barcodeOrientationMode = mode
    }

    fun updateTdFeedMode(mode: TdFeedMode) {
        tdFeedMode = mode
    }

    fun updateSnapTuningSettings(settings: SnapTuningSettings) {
        snapTuningSettings = settings
        snapTuningPreferences.save(settings)
    }

    fun resetSnapTuningSettings() {
        snapTuningSettings = snapTuningPreferences.reset()
    }

    fun updateSession(updatedState: TdSessionState) {
        val previousState = sessionState
        sessionState = updatedState

        if (autosaveEnabled) {
            if (shouldTriggerAutosave(previousState, updatedState)) {
                autosaveManager.save(sessionState, currentAutosaveFilename)
            }
        }
    }

    fun wipeSession() {
        sessionState = TdSessionState()
        // Note: we don't delete the autosave file here, giving the TD a "last train" recovery
    }

    private fun shouldTriggerAutosave(old: TdSessionState, new: TdSessionState): Boolean {
        val oldSummary = old.boards.mapValues { BoardProgressSummary.from(it.value.boardState) }
        val newSummary = new.boards.mapValues { BoardProgressSummary.from(it.value.boardState) }

        return newSummary.any { (boardNum, summary) ->
            val oldBoardSummary = oldSummary[boardNum]
            summary.completeSeats.size > (oldBoardSummary?.completeSeats?.size ?: 0)
        }
    }

    fun updateAutosaveEnabled(enabled: Boolean) {
        autosaveEnabled = enabled
        prefs.edit { putBoolean("autosave_enabled", enabled) }
    }

    fun updateAutosavePrefix(prefix: String) {
        autosavePrefix = prefix
        prefs.edit { putString("autosave_prefix", prefix) }
        currentAutosaveFilename = autosaveManager.generateFilename(prefix)
    }

    fun clearOldFiles(archive: Boolean) {
        if (archive) {
            autosaveManager.archiveFiles(oldAutosaveFiles)
        } else {
            autosaveManager.deleteFiles(oldAutosaveFiles)
        }
        oldAutosaveFiles = emptyList()
    }

    fun selectProfile(profileId: String) {
        profileState = profileState.copy(activeProfileId = profileId)
    }

    fun addProfile(profileName: String) {
        val newProfile = ProfileListItem(
            id = profileState.nextCustomProfileId(),
            displayName = profileName,
            isBuiltIn = false,
            isDemo = false,
            signatureModel = DeckProfileSignatureModels.GRID13_V2,
        )
        profileState = profileState.copy(
            profiles = profileState.profiles + newProfile,
            activeProfileId = newProfile.id,
        )
        editedProfiles = editedProfiles + (newProfile.id to newProfile.toEmptyDeckProfile())
    }

    fun deleteActiveProfile() {
        val toDelete = profileState.activeProfileId
        val newProfiles = profileState.profiles.filter { it.id != toDelete }
        profileState = profileState.copy(
            profiles = newProfiles,
            activeProfileId = newProfiles.firstOrNull()?.id ?: builtInDefaultMetadata.id,
        )
        editedProfiles = editedProfiles - toDelete
    }

    fun importProfile(importedProfile: DeckProfile) {
        val metadataItem = importedProfile.metadata.toProfileListItem()
            .copy(
                id = profileState.nextCustomProfileId(),
                isBuiltIn = false,
                isDemo = false
            )
        val finalizedProfile = importedProfile.withMetadata(metadataItem.toDeckProfileMetadata())

        profileState = profileState.copy(
            profiles = profileState.profiles + metadataItem,
            activeProfileId = metadataItem.id,
        )
        editedProfiles = editedProfiles + (metadataItem.id to finalizedProfile)
    }

    fun saveEditedProfile(updatedProfile: DeckProfile) {
        editedProfiles = editedProfiles + (activeProfileItem.id to updatedProfile)
        currentScreen = Screen.AdminActions
    }
}

package org.itroboc.app

import android.Manifest
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.compose.setContent
import androidx.activity.result.contract.ActivityResultContracts
import androidx.activity.viewModels
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier

class MainActivity : ComponentActivity() {
    private val viewModel: ItrobocMainViewModel by viewModels()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        AdminEditScanDebugLogStartup.clearOnce(this)
        setContent {
            MaterialTheme {
                Surface(modifier = Modifier.fillMaxSize()) {
                    AppNavigation(viewModel)
                }
            }
        }
    }
}

@Composable
fun AppNavigation(viewModel: ItrobocMainViewModel) {
    val activeProfileItem = viewModel.activeProfileItem
    val activeDeckProfile = viewModel.activeDeckProfile

    // Global Camera Permission Ceremony
    val launcher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestPermission(),
        onResult = { granted ->
            viewModel.updateCameraPermission(granted)
        }
    )

    LaunchedEffect(viewModel.hasCameraPermission) {
        if (!viewModel.hasCameraPermission) {
            launcher.launch(Manifest.permission.CAMERA)
        }
    }

    when (val screen = viewModel.currentScreen) {
        is Screen.MainMenu -> {
            MainMenuScreen(onNavigate = { viewModel.navigateTo(it) })
        }
        is Screen.TdActions -> {
            TdOverviewScreen(
                sessionState = viewModel.sessionState,
                activeProfile = activeProfileItem,
                autosaveEnabled = viewModel.autosaveEnabled,
                autosavePrefix = viewModel.autosavePrefix,
                autosavePath = viewModel.autosavePath,
                snapTuningSettings = viewModel.snapTuningSettings,
                oldFilesCount = viewModel.oldAutosaveFiles.size,
                onSessionStateChange = { viewModel.updateSession(it) },
                onAutosaveEnabledChange = { viewModel.updateAutosaveEnabled(it) },
                onAutosavePrefixChange = { viewModel.updateAutosavePrefix(it) },
                onSnapTuningSettingsChange = { viewModel.updateSnapTuningSettings(it) },
                onResetSnapTuningSettings = { viewModel.resetSnapTuningSettings() },
                onClearOldFiles = { viewModel.clearOldFiles(it) },
                onWipeSession = { viewModel.wipeSession() },
                onNavigateToBoard = { viewModel.navigateTo(Screen.EditBoard(it)) },
                onBack = { viewModel.navigateTo(Screen.MainMenu) }
            )
        }
        is Screen.EditBoard -> {
            val boardEditState = viewModel.sessionState.getOrInitBoard(screen.boardNumber)
            key(screen.boardNumber) {
                EditBoardScreen(
                    boardEditState = boardEditState,
                    deckProfile = activeDeckProfile,
                    orientationMode = viewModel.barcodeOrientationMode,
                    feedMode = viewModel.tdFeedMode,
                    requiredConsensusFrames = viewModel.sessionState.requiredConsensusFrames,
                    snapTuningSettings = viewModel.snapTuningSettings,
                    totalBoardsInGrid = viewModel.sessionState.totalBoardsInGrid,
                    onOrientationModeChange = { viewModel.updateOrientation(it) },
                    onFeedModeChange = { viewModel.updateTdFeedMode(it) },
                    onBoardEditStateChange = { updatedState ->
                        viewModel.updateSession(viewModel.sessionState.updateBoard(updatedState))
                    },
                    onNavigateToBoard = { boardNumber ->
                        viewModel.navigateTo(Screen.EditBoard(boardNumber))
                    },
                    onBack = { viewModel.navigateTo(Screen.TdActions) }
                )
            }
        }
        is Screen.AdminActions -> {
            AdminActionsScreen(
                uiState = viewModel.profileState,
                onSelectProfile = { viewModel.selectProfile(it) },
                onAddProfile = { viewModel.addProfile(it) },
                onDeleteActiveProfile = { viewModel.deleteActiveProfile() },
                onExportActiveProfile = { activeDeckProfile },
                onImportProfile = { viewModel.importProfile(it) },
                onEdit = { viewModel.navigateTo(Screen.AdminEdit) },
                onBack = { viewModel.navigateTo(Screen.MainMenu) },
            )
        }
        is Screen.AdminCalibrate -> {
//            AdminCalibrateScreen(
//            )
        }
        is Screen.AdminEdit -> {
            val editor = remember(activeProfileItem.id) { activeDeckProfile.toEditor() }
            AdminEditScreen(
                editor = editor,
                hasCameraPermission = viewModel.hasCameraPermission,
                onSave = { updatedProfile ->
                    viewModel.saveEditedProfile(updatedProfile)
                },
                onBack = { viewModel.navigateTo(Screen.AdminActions) }
            )
        }
    }
}

package org.itroboc.app

import org.itroboc.core.ActiveBoardView
import org.itroboc.core.CardId
import org.itroboc.core.Seat
import org.itroboc.vision.GrayImage
import org.itroboc.vision.SnapFrameRegion
import org.itroboc.vision.SnapFrameSize

@JvmInline
internal value class ImpressionGeneration(val value: Long) {
    init {
        require(value > 0L) { "Impression generation must be positive" }
    }

    fun next(): ImpressionGeneration = ImpressionGeneration(value + 1L)
}

/** Unique identity for a specific capture attempt; increments on every arm. */
@JvmInline
internal value class ImpressionCorrelationId(val value: Long) {
    init {
        require(value > 0L) { "Impression correlation ID must be positive" }
    }
}

internal data class ImpressionCaptureRequest(
    val generation: ImpressionGeneration,
    val correlationId: ImpressionCorrelationId,
    val seedCardId: CardId,
    val seedSignature: String,
    val targetSeat: Seat,
    val boardNumber: Int,
    val boardView: ActiveBoardView,
    val orientationMode: BarcodeOrientationMode,
    val configurationGeneration: StreamConfigurationGeneration,
    val sourceFrameSize: SnapFrameSize,
    val streamRoi: SnapFrameRegion,
) {
    init {
        require(seedSignature.isNotBlank()) { "Impression seed signature must not be blank" }
        require(boardNumber > 0) { "Impression board number must be positive" }
        require(boardView.boardNumber == boardNumber) {
            "Impression board view must match its board number"
        }
        require(boardView.targetSeat == targetSeat) {
            "Impression board view must match its target seat"
        }
        require(boardView.isInTargetHand(seedCardId)) {
            "Impression board view must contain its live seed in the target hand"
        }
        require(orientationMode != BarcodeOrientationMode.AUTO) {
            "Impression capture requires an explicit orientation mode"
        }
        require(streamRoi.fitsWithin(sourceFrameSize)) {
            "Stream ROI must fit within the source frame"
        }
    }
}

/** Defensively owned retained luma for one source-frame region. */
internal class ImpressionLumaReservoir internal constructor(
    val sourceRegion: SnapFrameRegion,
    packedLumaPixels: ByteArray,
) {
    private val packedLumaPixels = packedLumaPixels.copyOf()

    init {
        require(packedLumaPixels.size.toLong() == sourceRegion.width.toLong() * sourceRegion.height) {
            "Impression reservoir pixels must match its source region"
        }
    }

    fun copyPixels(): ByteArray = packedLumaPixels.copyOf()

    internal fun copyRegion(region: SnapFrameRegion): ByteArray {
        require(
            region.x >= sourceRegion.x &&
                region.y >= sourceRegion.y &&
                region.rightExclusive <= sourceRegion.rightExclusive &&
                region.bottomExclusive <= sourceRegion.bottomExclusive
        ) { "Selected region must fit within its Impression reservoir" }

        val localX = region.x - sourceRegion.x
        val localY = region.y - sourceRegion.y
        val selected = ByteArray(region.width * region.height)
        repeat(region.height) { row ->
            val sourceStart = (localY + row) * sourceRegion.width + localX
            packedLumaPixels.copyInto(
                destination = selected,
                destinationOffset = row * region.width,
                startIndex = sourceStart,
                endIndex = sourceStart + region.width,
            )
        }
        return selected
    }

    fun toGrayImage(): GrayImage = GrayImage(
        width = sourceRegion.width,
        height = sourceRegion.height,
        pixels = copyPixels(),
    )
}

/** Immutable presentation snapshot for Main. */
internal data class ImpressionPresentation(
    val generation: ImpressionGeneration,
    val correlationId: ImpressionCorrelationId,
    val geometry: ImpressionSceneGeometry,
    val saa: ImpressionLumaReservoir,
    val sab: ImpressionLumaReservoir,
    val rotationDegrees: Int,
)

internal sealed interface ImpressionPresentationUpdate {
    data class Present(val snapshot: ImpressionPresentation) : ImpressionPresentationUpdate
    data object Cleared : ImpressionPresentationUpdate
}

/** Captured scene data in unrotated luma coordinates. */
internal class ImpressionCaptured internal constructor(
    val request: ImpressionCaptureRequest,
    val geometry: ImpressionSceneGeometry,
    val saa: ImpressionLumaReservoir,
    val sab: ImpressionLumaReservoir,
    val rotationDegrees: Int,
    val timestampNanos: Long,
) {
    init {
        require(saa.sourceRegion == geometry.saa) { "SAA pixels must match SAA geometry" }
        require(sab.sourceRegion == geometry.sab) { "SAB pixels must match SAB geometry" }
        require(rotationDegrees in VALID_ROTATION_DEGREES) {
            "Rotation degrees must be one of $VALID_ROTATION_DEGREES"
        }
    }

    private companion object {
        val VALID_ROTATION_DEGREES = setOf(0, 90, 180, 270)
    }
}

internal fun ImpressionCaptured.toPresentation(): ImpressionPresentation =
    ImpressionPresentation(
        generation = request.generation,
        correlationId = request.correlationId,
        geometry = geometry,
        saa = saa,
        sab = sab,
        rotationDegrees = rotationDegrees,
    )

internal sealed interface ImpressionCaptureOutcome {
    val request: ImpressionCaptureRequest

    data class Captured(val impression: ImpressionCaptured) : ImpressionCaptureOutcome {
        override val request: ImpressionCaptureRequest = impression.request
    }

    data class Failed(
        override val request: ImpressionCaptureRequest,
        val reason: String,
    ) : ImpressionCaptureOutcome {
        init {
            require(reason.isNotBlank()) { "Impression capture failure reason must not be blank" }
        }
    }
}

/** Retained scene geometry in unrotated luma coordinates. */
internal data class ImpressionSceneGeometry(
    val saa: SnapFrameRegion,
    val sab: SnapFrameRegion,
)

internal fun computeImpressionSceneGeometry(
    frameSize: SnapFrameSize,
    streamRoi: SnapFrameRegion,
): ImpressionSceneGeometry {
    require(streamRoi.fitsWithin(frameSize)) {
        "Stream ROI must fit within the source frame"
    }

    // Reservoir horizontal bounds: deterministic clamped integer equivalents of frame 20%..80%
    val x = (frameSize.width.toLong() * 20L / 100L).toInt()
    val right = (frameSize.width.toLong() * 80L / 100L).toInt()
    val width = right - x

    require(width > 0) { "Frame width $width is too small for 20%..80% reservoir" }

    // SAA extends from frame top to slit top
    require(streamRoi.y > 0) { "Slit is at y=${streamRoi.y}; SAA would be empty" }
    val saa = SnapFrameRegion(
        x = x,
        y = 0,
        width = width,
        height = streamRoi.y
    )

    // SAB extends from slit bottom to frame bottom
    val sabStart = streamRoi.y + streamRoi.height
    require(sabStart < frameSize.height) {
        "Slit bottom is at $sabStart; SAB would be empty in ${frameSize.height} frame"
    }
    val sab = SnapFrameRegion(
        x = x,
        y = sabStart,
        width = width,
        height = frameSize.height - sabStart
    )

    return ImpressionSceneGeometry(saa = saa, sab = sab)
}

